algorithms.pseudocode:
def handle(event):
  if seen(event.source, event.dedup_key, event.status): return  # idempotent
  inc = open_incident_by_key(event.dedup_key)
  if not inc:
    related = catalog.neighbors(event.service, depth=2) | {event.service}
    inc = open_incident_where(service in related, opened_at > now-10m)
  if inc: attach(event, inc); maybe_raise_severity(inc, event)
  elif event.status == 'trigger':
    inc = create(event, sev=classifier.suggest(event))
    escalation.start(inc, policy_for(event.service))
  timeline.append(inc, event)
